update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(131,null::text,$$Concessão do livramento condicional$$,$$O livramento condicional pode ser concedido pelo juiz da execução, presentes os requisitos do artigo 83, incisos e parágrafo único, do Código Penal, ouvidos o Ministério Público e o Conselho Penitenciário.$$),
(132,null,$$Condições do livramento condicional$$,$$Deferido o pedido, o juiz especifica as condições do livramento. São sempre impostas ao liberado a obrigação de obter ocupação lícita, comunicar periodicamente ao juiz sua ocupação e não mudar do território da comarca sem prévia autorização (§ 1º, a a c). Podem ainda ser impostas, entre outras, não mudar de residência sem comunicação, recolher-se à habitação em hora fixada, não frequentar determinados lugares e utilizar equipamento de monitoração eletrônica (§ 2º, a, b, c e e).$$),
(133,null,$$Residência fora da comarca$$,$$Se for permitido ao liberado residir fora da comarca do juízo da execução, remete-se cópia da sentença do livramento ao juízo do lugar para onde ele se transferir e à autoridade incumbida da observação cautelar e de proteção.$$),
(134,null,$$Apresentação do liberado$$,$$O liberado é advertido da obrigação de apresentar-se imediatamente às autoridades referidas no artigo anterior.$$),
(135,null,$$Reforma da sentença denegatória$$,$$Reformada a sentença denegatória do livramento, os autos baixam ao juízo da execução para as providências cabíveis.$$),
(136,null,$$Carta de livramento$$,$$Concedido o benefício, expede-se a carta de livramento com a cópia integral da sentença em 2 (duas) vias, remetendo-se uma à autoridade administrativa incumbida da execução e outra ao Conselho Penitenciário.$$),
(137,null,$$Cerimônia do livramento condicional$$,$$A cerimônia do livramento condicional é realizada solenemente no dia marcado pelo Presidente do Conselho Penitenciário, no estabelecimento onde a pena é cumprida. A sentença é lida ao liberando, na presença dos demais condenados (inciso I), a autoridade administrativa chama a atenção dele para as condições impostas (inciso II) e ele declara se as aceita (inciso III). Lavra-se termo em livro próprio (§ 1º), com cópia remetida ao juiz da execução (§ 2º).$$),
(138,null,$$Caderneta do liberado$$,$$Ao sair do estabelecimento penal, o liberado recebe, além do saldo do pecúlio e do que lhe pertencer, uma caderneta, que exibe à autoridade judiciária ou administrativa sempre que exigida. A caderneta contém a identificação do liberado, o texto impresso do Capítulo e as condições impostas (§ 1º, a a c); na falta dela, entrega-se salvo-conduto com as condições do livramento (§ 2º).$$),
(139,null,$$Observação cautelar e proteção$$,$$A observação cautelar e a proteção, realizadas por serviço social penitenciário, Patronato ou Conselho da Comunidade, têm a finalidade de fazer observar o cumprimento das condições da sentença (inciso I) e de proteger o beneficiário, orientando-o na execução de suas obrigações e auxiliando-o na obtenção de atividade laborativa (inciso II). A entidade apresenta relatório ao Conselho Penitenciário (parágrafo único).$$),
(140,null,$$Revogação do livramento condicional$$,$$A revogação do livramento condicional dá-se nas hipóteses dos artigos 86 e 87 do Código Penal. Mantido o livramento na hipótese de revogação facultativa, o juiz deve advertir o liberado ou agravar as condições (parágrafo único).$$),
(141,null,$$Revogação por infração anterior$$,$$Se a revogação for motivada por infração penal anterior à vigência do livramento, computa-se como tempo de cumprimento da pena o período de prova, sendo permitida, para a concessão de novo livramento, a soma do tempo das 2 (duas) penas.$$),
(142,null,$$Revogação por outro motivo$$,$$Na revogação por outro motivo, não se computa na pena o tempo em que o liberado esteve solto, e tampouco se concede, em relação à mesma pena, novo livramento.$$),
(143,null,$$Legitimidade para a revogação$$,$$A revogação é decretada a requerimento do Ministério Público, mediante representação do Conselho Penitenciário ou, de ofício, pelo juiz, ouvido o liberado.$$),
(144,null,$$Modificação das condições do livramento$$,$$O juiz, de ofício, a requerimento do Ministério Público, da Defensoria Pública ou mediante representação do Conselho Penitenciário, e ouvido o liberado, pode modificar as condições especificadas na sentença. O ato decisório é lido ao liberado por uma das autoridades ou funcionários indicados no inciso I do caput do art. 137, observado o disposto nos incisos II e III e §§ 1º e 2º do mesmo artigo.$$),
(145,null,$$Nova infração penal do liberado$$,$$Praticada pelo liberado outra infração penal, o juiz pode ordenar sua prisão, ouvidos o Conselho Penitenciário e o Ministério Público, suspendendo o curso do livramento, cuja revogação fica dependendo da decisão final.$$),
(146,null,$$Extinção da pena pelo livramento$$,$$O juiz, de ofício, a requerimento do interessado, do Ministério Público ou mediante representação do Conselho Penitenciário, julga extinta a pena privativa de liberdade se expirar o prazo do livramento sem revogação.$$),
(146,$$Art. 146-B$$,$$Monitoração eletrônica$$,$$O juiz pode definir a fiscalização por monitoração eletrônica quando autorizar a saída temporária no regime semiaberto (inciso II), determinar a prisão domiciliar (inciso IV), aplicar pena privativa de liberdade a ser cumprida nos regimes aberto ou semiaberto ou conceder progressão para eles (inciso VI), aplicar pena restritiva de direitos que limite a frequência a lugares específicos (inciso VII) ou conceder o livramento condicional (inciso VIII). Os incisos I, III e V e o parágrafo único constam como vetados.$$),
(146,$$Art. 146-C$$,$$Deveres do monitorado$$,$$O condenado é instruído sobre os cuidados com o equipamento eletrônico e sobre os deveres de receber visitas do servidor responsável, responder aos seus contatos e cumprir suas orientações (inciso I) e de abster-se de remover, violar, modificar ou danificar o dispositivo ou permitir que outrem o faça (inciso II). A violação comprovada pode acarretar, a critério do juiz da execução, medidas como a regressão do regime (parágrafo único, inciso I), a revogação da saída temporária (inciso II), da prisão domiciliar (inciso VI) ou do livramento condicional (inciso VIII), a conversão da pena restritiva de direitos em privativa de liberdade (inciso IX) ou advertência por escrito (inciso VII).$$),
(146,$$Art. 146-D$$,$$Revogação da monitoração eletrônica$$,$$A monitoração eletrônica pode ser revogada quando se tornar desnecessária ou inadequada (inciso I) ou se o acusado ou condenado violar os deveres a que estiver sujeito durante a sua vigência ou cometer falta grave (inciso II).$$),
(146,$$Art. 146-E$$,$$Monitoração obrigatória em saídas$$,$$O condenado por crime contra a mulher por razões da condição do sexo feminino, nos termos do § 1º do art. 121-A do Código Penal, ou por crimes contra a dignidade sexual, ao usufruir de qualquer benefício que implique sua saída do estabelecimento penal, é fiscalizado por monitoração eletrônica.$$),
(147,null,$$Execução das penas restritivas de direitos$$,$$Transitada em julgado a sentença que aplicou a pena restritiva de direitos, o juiz da execução, de ofício ou a requerimento do Ministério Público, promove a execução, podendo requisitar, quando necessário, a colaboração de entidades públicas ou solicitá-la a particulares.$$),
(148,null,$$Alteração da forma de cumprimento$$,$$Em qualquer fase da execução, o juiz pode, motivadamente, alterar a forma de cumprimento das penas de prestação de serviços à comunidade e de limitação de fim de semana, ajustando-as às condições pessoais do condenado e às características do estabelecimento, da entidade ou do programa comunitário ou estatal.$$),
(149,null,$$Atribuições do juiz na prestação de serviços$$,$$Cabe ao juiz da execução designar a entidade ou programa comunitário ou estatal, credenciado ou convencionado, junto ao qual o condenado trabalha gratuitamente, de acordo com suas aptidões (inciso I), determinar a intimação do condenado, cientificando-o da entidade, dos dias e do horário (inciso II) e alterar a forma de execução para ajustá-la às modificações da jornada de trabalho (inciso III). O trabalho tem a duração de 8 (oito) horas semanais, realizado aos sábados, domingos e feriados ou em dias úteis, de modo a não prejudicar a jornada normal (§ 1º), e a execução começa na data do primeiro comparecimento (§ 2º).$$),
(150,null,$$Relatório da entidade beneficiada$$,$$A entidade beneficiada com a prestação de serviços encaminha mensalmente ao juiz da execução relatório circunstanciado das atividades do condenado e, a qualquer tempo, comunicação sobre ausência ou falta disciplinar.$$),
(151,null,$$Intimação na limitação de fim de semana$$,$$Cabe ao juiz da execução determinar a intimação do condenado, cientificando-o do local, dos dias e do horário em que deve cumprir a pena. A execução tem início a partir da data do primeiro comparecimento (parágrafo único).$$),
(152,null,$$Cursos, palestras e programas de reeducação$$,$$Podem ser ministrados ao condenado, durante o tempo de permanência, cursos e palestras, ou atribuídas atividades educativas. Nos casos de violência doméstica e familiar contra a criança, o adolescente e a mulher e de tratamento cruel ou degradante ou uso de formas violentas de educação, correção ou disciplina contra a criança e o adolescente, o juiz pode determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação (parágrafo único).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;